(function(root){'use strict';
 const parts={frontal:['Лобные доли','#bb8e68','Передние области полушарий; участие в организации действий и многих когнитивных процессах.'],parietal:['Теменные доли','#8bab92','Верхние задние области; интеграция соматосенсорной и пространственной информации.'],temporal:['Височные доли','#c8aa63','Нижние боковые области; участие в слухе, памяти и других процессах.'],occipital:['Затылочные доли','#8da9bf','Задние области; существенное участие в обработке зрительной информации.'],cerebellum:['Мозжечок','#a68ba7','Позади ствола и ниже задних отделов полушарий; участие в координации.'],stem:['Ствол мозга','#bd987c','Связывает вышележащие отделы со спинным мозгом; содержит множество ядер и путей.'],thalamus:['Таламус','#bd775e','Парные глубокие структуры промежуточного мозга; многочисленные связи с корой.'],callosum:['Мозолистое тело','#e4d7ac','Белое вещество крупной комиссуры между полушариями.']};
 function mesh(center,radii,kind){const vertices=[],faces=[],rows=12,cols=24;for(let r=0;r<=rows;r++)for(let c=0;c<=cols;c++){const a=Math.PI*r/rows,b=2*Math.PI*c/cols;vertices.push([center[0]+radii[0]*Math.sin(a)*Math.cos(b),center[1]+radii[1]*Math.cos(a),center[2]+radii[2]*Math.sin(a)*Math.sin(b)]);}for(let r=0;r<rows;r++)for(let c=0;c<cols;c++){const a=r*(cols+1)+c,b=a+cols+1;for(const ids of [[a,b,a+1],[a+1,b,b+1]]){const vs=ids.map(i=>vertices[i]),mean=vs[0].map((_,i)=>(vs[0][i]+vs[1][i]+vs[2][i])/3);const region=kind==='cortex'?(mean[2]>.32?'frontal':mean[2]<-.62?'occipital':mean[1]<-.1?'temporal':'parietal'):kind;faces.push({vs,region});}}return faces;}
 function mount(view,controls,H){const{n,range,select,check,readout}=H,canvas=n('canvas');canvas.width=1280;canvas.height=840;canvas.tabIndex=0;canvas.setAttribute('role','img');canvas.setAttribute('aria-label','Вращаемая трёхмерная схема мозга. Стрелки меняют ракурс, Home возвращает исходный. Ползунки и список структур дают эквивалентное управление.');view.append(canvas,n('p','Перетащите для вращения; короткое нажатие выбирает видимую область. Стрелки — поворот, Home — исходный вид.','neuro-caption'));const ctx=canvas.getContext('2d');let yaw=-.45,pitch=.25,selected='frontal',hemispheres=true,deep=false,projected=[],drag=null,moved=0;
 const cortical=[...mesh([-.48,.05,.05],[.48,.78,1.05],'cortex'),...mesh([.48,.05,.05],[.48,.78,1.05],'cortex')],other=[...mesh([0,-.59,-.84],[.66,.43,.48],'cerebellum'),...mesh([0,-1.04,-.27],[.23,.63,.25],'stem')],inside=[...mesh([-.15,-.12,0],[.19,.25,.32],'thalamus'),...mesh([.15,-.12,0],[.19,.25,.32],'thalamus'),...mesh([0,.2,.02],[.11,.2,.64],'callosum')];
 const region=select(controls,'Структура',Object.entries(parts).map(([id,p])=>[id,p[0]]),selected,v=>{selected=v;if(v==='thalamus'||v==='callosum'){deep=true;hemispheres=false;layers.input.checked=false;inner.input.checked=true;}draw();});const yawControl=range(controls,'Поворот по горизонтали',-180,180,-26,1,'°',v=>{yaw=v*Math.PI/180;draw();}),pitchControl=range(controls,'Наклон',-70,70,14,1,'°',v=>{pitch=v*Math.PI/180;draw();});const layers=check(controls,'Показать полушария',true,v=>{hemispheres=v;draw();}),inner=check(controls,'Показать глубокие структуры',false,v=>{deep=v;draw();}),info=readout(controls),reset=n('button','Исходный ракурс','quiet outlined');reset.type='button';reset.onclick=()=>{yaw=-.45;pitch=.25;sync();draw();};controls.append(reset);
 function rotate(p){const x=p[0]*Math.cos(yaw)+p[2]*Math.sin(yaw),z=-p[0]*Math.sin(yaw)+p[2]*Math.cos(yaw);return[x,p[1]*Math.cos(pitch)-z*Math.sin(pitch),p[1]*Math.sin(pitch)+z*Math.cos(pitch)];}function project(v){return[320+v[0]*110/(1-v[2]/6),196-v[1]*110/(1-v[2]/6),v[2]];}
 function sync(){yawControl.set(Math.round(yaw*180/Math.PI));pitchControl.set(Math.round(pitch*180/Math.PI));}
 function draw(){ctx.setTransform(2,0,0,2,0,0);ctx.clearRect(0,0,640,420);const faces=[...(hemispheres?cortical:[]),...other,...(deep?inside:[])];projected=faces.map(f=>{const v=f.vs.map(rotate),p=v.map(project);return{p,region:f.region,depth:v.reduce((s,p)=>s+p[2],0)/3};}).sort((a,b)=>a.depth-b.depth);for(const f of projected){ctx.beginPath();ctx.moveTo(...f.p[0].slice(0,2));ctx.lineTo(...f.p[1].slice(0,2));ctx.lineTo(...f.p[2].slice(0,2));ctx.closePath();ctx.fillStyle=f.region===selected?'#ff2d95':parts[f.region][1];ctx.globalAlpha=f.region===selected?1:.6;ctx.fill();ctx.globalAlpha=1;ctx.strokeStyle=f.region===selected?'#ffffff33':'#35574712';ctx.lineWidth=.35;ctx.stroke();}ctx.font='13px Segoe UI';ctx.fillStyle='#263f37';for(const [label,p]of [['Перед',[0,0,1.5]],['Зад',[0,0,-1.5]],['Лево',[-1.4,0,0]],['Право',[1.4,0,0]],['Верх',[0,1.2,0]]]){const v=project(rotate(p));ctx.fillText(label,v[0]-14,v[1]);}ctx.fillText('Учебная 3D-схема · границы приблизительны',14,400);info.replaceChildren(n('strong',parts[selected][0]),n('p',parts[selected][2]));region.value=selected;canvas.dataset.region=selected;canvas.dataset.yaw=String(yaw);canvas.dataset.faces=String(projected.length);}
 canvas.addEventListener('pointerdown',e=>{drag=[e.clientX,e.clientY];moved=0;canvas.setPointerCapture(e.pointerId);});canvas.addEventListener('pointermove',e=>{if(!drag)return;const dx=e.clientX-drag[0],dy=e.clientY-drag[1];moved+=Math.abs(dx)+Math.abs(dy);yaw+=dx*.012;pitch=Math.max(-1.2,Math.min(1.2,pitch+dy*.008));drag=[e.clientX,e.clientY];sync();draw();});canvas.addEventListener('pointerup',e=>{if(!drag)return;drag=null;if(moved<6){const r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)/r.width*640,y=(e.clientY-r.top)/r.height*420;const inside=(a,b,c)=>{const s=(a[0]-x)*(b[1]-y)-(b[0]-x)*(a[1]-y),t=(b[0]-x)*(c[1]-y)-(c[0]-x)*(b[1]-y),u=(c[0]-x)*(a[1]-y)-(a[0]-x)*(c[1]-y);return(s>=0&&t>=0&&u>=0)||(s<=0&&t<=0&&u<=0);};const hit=[...projected].reverse().find(f=>inside(...f.p));if(hit){selected=hit.region;draw();}}});canvas.addEventListener('pointercancel',()=>drag=null);canvas.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home'].includes(e.key))return;e.preventDefault();if(e.key==='Home'){yaw=-.45;pitch=.25;}else{yaw+=e.key==='ArrowLeft'?-.1:e.key==='ArrowRight'?.1:0;pitch=Math.max(-1.2,Math.min(1.2,pitch+(e.key==='ArrowUp'?.1:e.key==='ArrowDown'?-.1:0)));}sync();draw();});draw();return()=>{drag=null;};
 }
 root.BrainAtlas={mount};
})(globalThis);
